entries[367618] = { ["name"] = "Unstable Frostfire Belt", ["text"] = "5 sec cast 3\nTools: Blacksmith Hammer\nReagents:\nFrosty Soul , Fiery Soul , Frostfire Alloy (13), Spark (#247)\nOptional Reagents:\nZone:\nAlgeth'ar Academy & The Azure Vault\nRecipe:\nPurchasable on the Auction House\n\nUnstable Frostfire Belt\nBinds when picked up\nWaist Plate\n469 Armor\n+193 [Strength or Intellect]+312 Stamina\n+ 256 Critical Strike\n+ 102 Mastery\nDurability 55 / 55\nEquip: Your spells and abilities have a chance to inflict a Lingering Frostspark, dealing [source value] Frostfire damage over 10 sec. Enemies that die while under this effect will explode, leaving a cold sleet for 8 sec that slows enemies by 50%.\n70", ["unresolvedValues"] = true }
